```javascript
import { 
  Group, Mesh, PlaneGeometry, CylinderGeometry, ExtrudeGeometry, Shape,
  MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, DirectionalLight,
  AdditiveBlending, DoubleSide
} from 'three/webgpu';

import {
  uv, mix, color, step, abs, mul, add, smoothstep, vec2, length, sub
} from 'three/tsl';

import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // ---- extract data ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const cardsData = [];
  for (let i = 0; i < 3; i++) {
    const iconItem = items[i * 3];
    const titleItem = items[i * 3 + 1];
    const bodyItem = items[i * 3 + 2];
    if (iconItem && titleItem && bodyItem) {
      cardsData.push({
        icon: iconItem.text,
        title: titleItem.text,
        body: bodyItem.text,
      });
    }
  }

  // ---- design tokens ----
  const { THREE } = ctx;
  const gradientStops = config.intent.visualSpec.colors.gradientStops;
  const topColor = new THREE.Color(gradientStops[0].hex);
  const bottomColor = new THREE.Color(gradientStops[1].hex);
  const borderColor = new THREE.Color('#26262f');
  const accentColor = new THREE.Color('#ff2a38');

  const cardW = 1.5;
  const cardH = 1.9;
  const cornerRad = 0.06;
  const gap = 0.25;
  const totalWidth = 3 * cardW + 2 * gap;
  const cardPositions = [
    new THREE.Vector3(-(cardW + gap), 0, 0),
    new THREE.Vector3(0, 0, 0),
    new THREE.Vector3(cardW + gap, 0, 0),
  ];

  // ---- helper: thick card mesh ----
  const createCardMesh = () => {
    const shape = new Shape();
    const w2 = cardW / 2;
    const h2 = cardH / 2;
    const r = cornerRad;
    shape.moveTo(-w2 + r, -h2);
    shape.lineTo(w2 - r, -h2);
    shape.quadraticCurveTo(w2, -h2, w2, -h2 + r);
    shape.lineTo(w2, h2 - r);
    shape.quadraticCurveTo(w2, h2, w2 - r, h2);
    shape.lineTo(-w2 + r, h2);
    shape.quadraticCurveTo(-w2, h2, -w2, h2 - r);
    shape.lineTo(-w2, -h2 + r);
    shape.quadraticCurveTo(-w2, -h2, -w2 + r, -h2);

    const extrudeSettings = {
      depth: 0.04,
      bevelEnabled: true,
      bevelThickness: 0.01,
      bevelSize: 0.005,
      bevelSegments: 3,
    };
    const geo = new ExtrudeGeometry(shape, extrudeSettings);
    const mat = new MeshPhysicalNodeMaterial({
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      side: DoubleSide,
    });

    // TSL gradient + border
    const uvNode = uv().mul(2).sub(1);                // [-1, 1]
    const gradientMix = uvNode.y.mul(0.5).add(0.5);   // 0-1
    const gradColor = mix(
      color(topColor.r, topColor.g, topColor.b),
      color(bottomColor.r, bottomColor.g, bottomColor.b),
      gradientMix
    );

    const borderWidth = (0.006 / cardW) * 2;          // in UV space (range 2)
    const u = uvNode.x;
    const v = uvNode.y;
    const borderMask = step(abs(u), 1 - borderWidth).mul(step(abs(v), (cardH / cardW) - borderWidth));
    const finalColor = mix(
      color(borderColor.r, borderColor.g, borderColor.b),
      gradColor,
      borderMask
    );
    mat.colorNode = finalColor;

    const mesh = new Mesh(geo, mat);
    mesh.rotation.y = Math.PI;   // front face toward camera
    return mesh;
  };

  // ---- helper: shadow material ----
  const createShadowMat = () => {
    const mat = new MeshBasicNodeMaterial({
      transparent: true,
      depthWrite: false,
      blending: AdditiveBlending,
      color: new THREE.Color(0x000000),
    });
    const uvNode = uv();
    const dist = sub(uvNode, vec2(0.5)).length().mul(2);
    const opacityNode = smoothstep(0.6, 0.0, dist).mul(0.6);
    mat.opacityNode = opacityNode;
    return mat;
  };

  // ---- helper: icon disc ----
  const createDisc = () => {
    const geo = new CylinderGeometry(0.2, 0.2, 0.05, 32);
    const mat = new MeshPhysicalNodeMaterial({
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      clearcoatRoughness: 0.1,
      anisotropy: 0.6,
      anisotropyRotation: 0,
      color: new THREE.Color('#16161d'),
      envMapIntensity: 1.0,
    });
    return new Mesh(geo, mat);
  };

  // ---- build cards ----
  const cards = [];
  const shadowGroups = [];

  cardsData.forEach((data, idx) => {
    const cardGroup = new Group();
    cardGroup.position.copy(cardPositions[idx]);
    cardGroup.userData.initialY = cardPositions[idx].y;

    // card body
    const cardMesh = createCardMesh();
    cardGroup.add(cardMesh);

    // hairline border loop
    const shape = new Shape();
    const w2 = cardW / 2, h2 = cardH / 2, r = cornerRad;
    shape.moveTo(-w2 + r, -h2);
    shape.lineTo(w2 - r, -h2);
    shape.quadraticCurveTo(w2, -h2, w2, -h2 + r);
    shape.lineTo(w2, h2 - r);
    shape.quadraticCurveTo(w2, h2, w2 - r, h2);
    shape.lineTo(-w2 + r, h2);
    shape.quadraticCurveTo(-w2, h2, -w2, h2 - r);
    shape.lineTo(-w2, -h2 + r);
    shape.quadraticCurveTo(-w2, -h2, -w2 + r, -h2);
    const points = shape.getPoints(50);
    const borderGeo = new THREE.BufferGeometry().setFromPoints(
      points.map(p => new THREE.Vector3(p.x, p.y, 0.022)) // slightly in front
    );
    const borderLine = new THREE.LineLoop(
      borderGeo,
      new THREE.LineBasicMaterial({ color: borderColor })
    );
    cardGroup.add(borderLine);

    // disc
    const disc = createDisc();
    disc.position.set(0, 0.575, 0.025);
    cardGroup.add(disc);

    // icon text
    const iconText = ctx.fontAtlas.createText(data.icon, {
      fontSize: 20,
      color: '#ff2a38',
      align: 'center',
    });
    if (iconText.material) {
      iconText.material.color.setHex(0xff2a38);
      if (iconText.material.emissive) {
        iconText.material.emissive.setHex(0xff2a38);
        iconText.material.emissiveIntensity = 1.6;
      }
    }
    iconText.position.set(0, 0.575, 0.035);
    cardGroup.add(iconText);

    // title text
    const titleText = ctx.fontAtlas.createText(data.title, {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'center',
    });
    titleText.position.set(0, 0.325, 0.035);
    cardGroup.add(titleText);

    // body text
    const bodyText = ctx.fontAtlas.createText(data.body, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 1.2 * cardW,
    });
    bodyText.position.set(0, 0.2, 0.035);
    cardGroup.add(bodyText);

    // contact shadow (placed in world group)
    const shadowGroup = new Group();
    shadowGroup.position.set(
      cardPositions[idx].x,
      -0.95,   // bottom of card
      -0.06
    );
    const shadowGeo = new PlaneGeometry(1.6 * cardW, 1.6 * cardH);
    const shadowMat = createShadowMat();
    const shadowMesh = new Mesh(shadowGeo, shadowMat);
    shadowMesh.rotation.x = -Math.PI / 2;
    shadowGroup.add(shadowMesh);
    group.add(shadowGroup);

    // store references
    cardGroup.userData.shadowGroup = shadowGroup;
    cardGroup.userData.shadowMesh = shadowMesh;
    cardGroup.userData.iconText = iconText;
    cardGroup.userData.disc = disc;

    group.add(cardGroup);
    cards.push(cardGroup);
    shadowGroups.push(shadowGroup);
  });

  // ---- lighting ----
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const fillLight = new DirectionalLight(0xffffff, 0.6);
  fillLight.position.set(-2, -1, 2);
  group.add(fillLight);

  const rimLight = new DirectionalLight(0xe8ecf2, 0.8);
  rimLight.position.set(-3, 1, -4);
  group.add(rimLight);

  // ---- entrance animation (stagger) ----
  const entranceTL = gsap.timeline();
  cards.forEach((card, i) => {
    const origY = card.position.y;
    card.position.y = origY + 0.2;
    card.opacity = 0;       // will be overridden by manual opacity handling
    entranceTL.to(card.position, {
      y: origY,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay: i * 0.08,
    }, 0);
    // opacity cannot be animated directly on Group, so we set children opacity
    card.children.forEach(child => {
      if (child.isMesh && child.material) {
        child.material.transparent = true;
        gsap.to(child.material, {
          opacity: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          delay: i * 0.08,
        });
      }
    });
  });

  // ---- hover lift ----
  cards.forEach(card => {
    const shadowGroup = card.userData.shadowGroup;
    const shadowMesh = card.userData.shadowMesh;
    const iconText = card.userData.iconText;

    const enter = () => {
      gsap.to(card.position, {
        y: card.userData.initialY + 0.06,
        z: 0.12,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      gsap.to(shadowMesh.scale, {
        x: 1.2, y: 1.2,
        duration: 0.18,
        ease: 'power2.out',
      });
      gsap.to(shadowMesh.material, {
        opacity: 0.6,
        duration: 0.18,
        ease: 'power2.out',
      });
      if (iconText.material) {
        gsap.to(iconText.material, {
          emissiveIntensity: 2.2,
          duration: 0.18,
          ease: 'power2.out',
        });
      }
    };

    const leave = () => {
      gsap.to(card.position, {
        y: card.userData.initialY,
        z: 0,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      gsap.to(shadowMesh.scale, {
        x: 1, y: 1,
        duration: 0.18,
        ease: 'power2.out',
      });
      gsap.to(shadowMesh.material, {
        opacity: 0.4,
        duration: 0.18,
        ease: 'power2.out',
      });
      if (iconText.material) {
        gsap.to(iconText.material, {
          emissiveIntensity: 1.6,
          duration: 0.18,
          ease: 'power2.out',
        });
      }
    };

    card.addEventListener('pointerenter', enter);
    card.addEventListener('pointerleave', leave);
    card.userData.handlers = { pointerenter: enter, pointerleave: leave };
  });

  // ---- cleanup ----
  group.userData.cleanup = () => {
    entranceTL.kill();
    cards.forEach(card => {
      card.removeEventListener('pointerenter', card.userData.handlers.pointerenter);
      card.removeEventListener('pointerleave', card.userData.handlers.pointerleave);
      card.traverse(child => {
        if (child.isMesh) {
          child.geometry.dispose();
          if (child.material) child.material.dispose();
        }
      });
    });
    shadowGroups.forEach(sg => {
      sg.children.forEach(child => {
        if (child.isMesh) {
          child.geometry.dispose();
          child.material.dispose();
        }
      });
    });
  };

  return group;
}
